const svg=$('#manifold-svg'), out=$('#manifold-out'), muSl=$('#mf-mu'), muL=$('#mf-mu-lbl'), sgSl=$('#mf-sig'), sgL=$('#mf-sig-lbl');
const W=640,H=360;
// top panel: the (mu, sigma) upper half-plane manifold
const mp={x0:48,x1:W-18,y0:24,y1:150};   // y0 top (sigma max), y1 bottom (sigma=0)
const MU0=-3,MU1=3, SG1=3.2;             // sigma in (0, SG1]
const MX=mu=>mp.x0+(mu-MU0)/(MU1-MU0)*(mp.x1-mp.x0);
const MY=sg=>mp.y1-(sg/SG1)*(mp.y1-mp.y0);
// bottom panel: the density p(x)
const dp={x0:48,x1:W-18,y0:H-30,y1:200};
const A=-7,B=7;
const DX=x=>dp.x0+(x-A)/(B-A)*(dp.x1-dp.x0);
let dlo=0,dhi=1.4; const DY=y=>dp.y0-(y-dlo)/(dhi-dlo)*(dp.y0-dp.y1);
function dens(x,mu,sg){ return Math.exp(-(x-mu)*(x-mu)/(2*sg*sg))/(sg*Math.sqrt(2*Math.PI)); }
function render(){
  svg.innerHTML='';
  const mu=+muSl.value, sg=+sgSl.value; muL.textContent='μ = '+mu.toFixed(1); sgL.textContent='σ = '+sg.toFixed(1);
  // ---- manifold panel ----
  svg.appendChild(SVG('rect',{x:mp.x0,y:mp.y0,width:mp.x1-mp.x0,height:mp.y1-mp.y0,fill:'none',stroke:'var(--line)'}));
  // sigma=0 boundary (the deleted edge of the half-plane)
  svg.appendChild(SVG('line',{x1:mp.x0,y1:mp.y1,x2:mp.x1,y2:mp.y1,stroke:'var(--pink)','stroke-width':1.5,'stroke-dasharray':'4 3'}));
  const bl=SVG('text',{x:mp.x1-4,y:mp.y1-5,'text-anchor':'end','font-size':10,fill:'var(--pink)'}); bl.textContent='σ = 0 (boundary, not in M)'; svg.appendChild(bl);
  const tlt=SVG('text',{x:mp.x0+4,y:mp.y0+13,'font-size':11,fill:'var(--mute)'}); tlt.textContent='manifold M = upper half-plane (μ, σ)'; svg.appendChild(tlt);
  const axm=SVG('text',{x:(mp.x0+mp.x1)/2,y:mp.y1+15,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); axm.textContent='μ'; svg.appendChild(axm);
  // a faint grid of sample points
  for(let gm=-3;gm<=3;gm+=1) for(let gs=0.5;gs<=3;gs+=0.5){ svg.appendChild(SVG('circle',{cx:MX(gm),cy:MY(gs),r:1.3,fill:'var(--line)'})); }
  // the chosen point
  svg.appendChild(SVG('circle',{cx:MX(mu),cy:MY(sg),r:5.5,fill:'var(--yellow)',stroke:'#111','stroke-width':1}));
  const plbl=SVG('text',{x:MX(mu)+9,y:MY(sg)-7,'font-size':11,fill:'var(--yellow)'}); plbl.textContent='p_θ'; svg.appendChild(plbl);
  // ---- density panel ----
  svg.appendChild(SVG('line',{x1:dp.x0,y1:dp.y0,x2:dp.x1,y2:dp.y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:dp.x0,y1:dp.y0,x2:dp.x0,y2:dp.y1,stroke:'var(--line)'}));
  const axd=SVG('text',{x:(dp.x0+dp.x1)/2,y:H-6,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); axd.textContent='x'; svg.appendChild(axd);
  const ayd=SVG('text',{x:dp.x0+6,y:dp.y1-4,'font-size':11,fill:'var(--mute)'}); ayd.textContent='p_θ(x)'; svg.appendChild(ayd);
  let d='M', N=240;
  for(let i=0;i<=N;i++){ const x=A+(B-A)*i/N; d+=` ${DX(x).toFixed(1)} ${DY(dens(x,mu,sg)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d,fill:'none',stroke:'var(--yellow)','stroke-width':2.2}));
  // mark the mean
  svg.appendChild(SVG('line',{x1:DX(mu),y1:dp.y0,x2:DX(mu),y2:DY(dens(mu,mu,sg)),stroke:'var(--cyan)','stroke-width':1,'stroke-dasharray':'3 3'}));
  out.textContent =
    `point on M:  (μ, σ) = (${mu.toFixed(2)}, ${sg.toFixed(2)})\n`+
    `scores at a sample x:  ∂_μℓ = (x−μ)/σ²,  ∂_σℓ = ((x−μ)²−σ²)/σ³\n`+
    `both have E_θ[score] = 0  —  the tangent space sits in mean-zero L²(p_θ)`;
}
muSl.addEventListener('input',render);
sgSl.addEventListener('input',render);
render();

const svg=$('#fisher-svg'), out=$('#fisher-out'), muSl=$('#fm-mu'), muL=$('#fm-mu-lbl'), sgSl=$('#fm-sig'), sgL=$('#fm-sig-lbl'), bBtn=$('#fm-balls');
const W=640,H=360, padL=50,padR=20,padT=24,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const MU0=-3,MU1=3, SG0=0,SG1=3.4;
const MX=mu=>x0+(mu-MU0)/(MU1-MU0)*(x1-x0);
const MY=sg=>y0-(sg-SG0)/(SG1-SG0)*(y0-y1);
let showField=true;
// Fisher metric of the Gaussian: G = diag(1/sig^2, 2/sig^2). A unit ball delta^T G delta = r^2
// has semi-axes r*sig (mu-direction) and r*sig/sqrt(2) (sigma-direction).
function ball(mu,sg,r,color,wd){
  // axis lengths in parameter space, mapped to pixels
  const aMu=r*sg, aSg=r*sg/Math.SQRT2;
  const rxPix=Math.abs(MX(mu+aMu)-MX(mu));
  const ryPix=Math.abs(MY(sg+aSg)-MY(sg));
  svg.appendChild(SVG('ellipse',{cx:MX(mu),cy:MY(sg),rx:rxPix,ry:ryPix,fill:'none',stroke:color,'stroke-width':wd}));
}
function render(){
  svg.innerHTML='';
  const mu=+muSl.value, sg=+sgSl.value; muL.textContent='μ = '+mu.toFixed(1); sgL.textContent='σ = '+sg.toFixed(1);
  // frame + axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  const axm=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axm.textContent='μ'; svg.appendChild(axm);
  const axs=SVG('text',{x:16,y:(y0+y1)/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)',transform:`rotate(-90 16 ${(y0+y1)/2})`}); axs.textContent='σ'; svg.appendChild(axs);
  // field of unit Fisher balls
  if(showField){
    for(let gm=-2.5;gm<=2.5;gm+=1.25) for(let gs=0.4;gs<=3.0;gs+=0.55){ ball(gm,gs,0.5,'var(--violet)',1); }
  }
  // highlighted ball at the base point
  ball(mu,sg,0.5,'var(--cyan)',2.2);
  svg.appendChild(SVG('circle',{cx:MX(mu),cy:MY(sg),r:4,fill:'var(--yellow)'}));
  // a step of fixed Euclidean size and its Fisher length
  const dMu=0.6, dSg=0.6;
  const gMM=1/(sg*sg), gSS=2/(sg*sg);
  const fisherLen=Math.sqrt(gMM*dMu*dMu + gSS*dSg*dSg);
  const euclLen=Math.hypot(dMu,dSg);
  drawArrow(svg,[MX(mu),MY(sg)],[MX(mu+dMu),MY(sg+dSg)],{color:'var(--yellow)',markerId:'fm-arr',width:2});
  out.textContent =
    `base (μ, σ) = (${mu.toFixed(2)}, ${sg.toFixed(2)})\n`+
    `Fisher matrix G = diag(1/σ², 2/σ²) = diag(${gMM.toFixed(3)}, ${gSS.toFixed(3)})\n`+
    `a step δ = (0.6, 0.6):  Euclidean ‖δ‖ = ${euclLen.toFixed(3)},  Fisher ‖δ‖_G = ${fisherLen.toFixed(3)}\n`+
    (sg<1 ? '→ small σ: G is large, the same parameter step is LONG in Fisher length'
          : '→ large σ: G is small, the same parameter step is SHORT in Fisher length');
}
muSl.addEventListener('input',render);
sgSl.addEventListener('input',render);
bBtn.addEventListener('click',()=>{ showField=!showField; bBtn.classList.toggle('active',!showField); render(); });
render();

const MX0=48, MX1=472, SY0=290, STOP=26, SMAX=4.2, R2=Math.SQRT2;
const mOf = px => -4 + (px-MX0)/(MX1-MX0)*8;
const sOf = py => (SY0-py)/(SY0-STOP)*SMAX;
const mpx = m => MX0 + (m+4)/8*(MX1-MX0);
const spx = sg => SY0 - sg/SMAX*(SY0-STOP);
const frDist=(m1,s1,m2,s2)=>R2*Math.acosh(1+((m1-m2)*(m1-m2)/2+(s1-s2)*(s1-s2))/(2*s1*s2));
function draw(){
  G.innerHTML='';
  // boundary sigma=0 and gridlines
  G.appendChild(SVG('line',{x1:MX0,y1:SY0,x2:MX1,y2:SY0,stroke:'var(--line)','stroke-width':1.5}));
  G.appendChild(SVG('line',{x1:MX0,y1:STOP,x2:MX0,y2:SY0,stroke:'var(--line)','stroke-width':1}));
  var b0=SVG('text',{x:MX1-4,y:SY0+15,'font-size':10,fill:'var(--mute)','text-anchor':'end','pointer-events':'none'}); b0.textContent='\u03c3\u21920: distributions collapse'; G.appendChild(b0);
  G.appendChild((function(){var t=SVG('text',{x:MX1,y:SY0+15,'font-size':11,fill:'var(--mute)','text-anchor':'end','pointer-events':'none'});t.textContent='';return t;})());
  var xl=SVG('text',{x:(MX0+MX1)/2,y:SY0+15,'font-size':11,fill:'var(--mute)','text-anchor':'middle','pointer-events':'none'}); xl.textContent='mean \u03bc'; G.appendChild(xl);
  for(var gm=-2;gm<=2;gm+=2){ G.appendChild(SVG('line',{x1:mpx(gm),y1:STOP,x2:mpx(gm),y2:SY0,stroke:'var(--line)','stroke-width':0.5,'stroke-opacity':0.3,'pointer-events':'none'})); }
  var p1=pts.byId['g1'], p2=pts.byId['g2'];
  var m1=mOf(p1.x), s1=sOf(p1.y), m2=mOf(p2.x), s2=sOf(p2.y);
  // straight chord (naive Euclidean) for contrast
  G.appendChild(SVG('line',{x1:p1.x,y1:p1.y,x2:p2.x,y2:p2.y,stroke:'var(--mute)','stroke-width':1,'stroke-dasharray':'4 4','pointer-events':'none'}));
  // Fisher-Rao geodesic: semi-ellipse (mu-mu0)^2/2 + sigma^2 = r^2
  var d='';
  if(Math.abs(m1-m2)<0.02){ d='M'+p1.x.toFixed(1)+' '+p1.y.toFixed(1)+'L'+p2.x.toFixed(1)+' '+p2.y.toFixed(1); }
  else { var mu0=(m1+m2)/2-(s2*s2-s1*s1)/(m1-m2); var r=Math.sqrt((m1-mu0)*(m1-mu0)/2+s1*s1);
    var th1=Math.atan2(s1,(m1-mu0)/R2), th2=Math.atan2(s2,(m2-mu0)/R2);
    var N=48; for(var i=0;i<=N;i++){ var th=th1+(th2-th1)*i/N; var mm=mu0+R2*r*Math.cos(th), ss=r*Math.sin(th); d+=(i?'L':'M')+mpx(mm).toFixed(1)+' '+spx(ss).toFixed(1)+' '; } }
  G.appendChild(SVG('path',{d:d,fill:'none',stroke:'var(--violet)','stroke-width':2.5,'pointer-events':'none'}));
  // mini-gaussian glyph at each point
  [{p:p1,m:m1,s:s1,c:'var(--cyan)'},{p:p2,m:m2,s:s2,c:'var(--pink)'}].forEach(function(o){
    var g=''; for(var k=-14;k<=14;k++){ var xx=o.p.x+k; var z=(k/14)*3; var yy=o.p.y-18-10*Math.exp(-z*z/2); g+=(k===-14?'M':'L')+xx.toFixed(1)+' '+yy.toFixed(1)+' '; }
    G.appendChild(SVG('path',{d:g,fill:'none',stroke:o.c,'stroke-width':1.2,'stroke-opacity':0.7,'pointer-events':'none'})); });
  var d12=frDist(m1,s1,m2,s2);
  out.innerHTML='$P_1=\\mathcal N('+m1.toFixed(1)+','+(s1*s1).toFixed(2)+')$, $P_2=\\mathcal N('+m2.toFixed(1)+','+(s2*s2).toFixed(2)+')$ &nbsp;\u00b7&nbsp; Fisher\u2013Rao distance <b>'+d12.toFixed(2)+'</b> &nbsp;\u00b7&nbsp; <span style=\"color:var(--mute)\">drag either Gaussian. The <span style=\"color:var(--violet)\">bold geodesic</span> bows toward <em>larger</em> $\\sigma$, away from the $\\sigma\\to0$ boundary \u2014 the metric $ds^2=(d\\mu^2+2\\,d\\sigma^2)/\\sigma^2$ is hyperbolic, so the shortest path is <em>not</em> the dashed straight line. Same-mean Gaussians sit $\\sqrt2\\,|\\ln(\\sigma_2/\\sigma_1)|$ apart.</span>';
  if(window.renderMathInElement) try{ renderMathInElement(out,{throwOnError:false,delimiters:[{left:'$',right:'$',display:false}]}); }catch(e){}
}

const svg=$('#klfisher-svg'), out=$('#klfisher-out'), pSl=$('#kf-p'), pL=$('#kf-p-lbl'), wSl=$('#kf-win'), wL=$('#kf-win-lbl');
const W=640,H=340, padL=56,padR=20,padT=24,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
// Bernoulli(p): KL(p || q) and Fisher g(p)=1/(p(1-p))
function klBer(p,q){ q=Math.min(0.999,Math.max(0.001,q));
  let s=0; if(p>0) s+=p*Math.log(p/q); if(p<1) s+=(1-p)*Math.log((1-p)/(1-q)); return s; }
function fisher(p){ return 1/(p*(1-p)); }
function render(){
  svg.innerHTML='';
  const p=+pSl.value, win=+wSl.value; pL.textContent='p = '+p.toFixed(2); wL.textContent='±'+win.toFixed(2);
  const g=fisher(p);
  // y-range: max of the two curves at the window edge
  const yMax=Math.max(klBer(p,p+win), klBer(p,p-win), 0.5*g*win*win)*1.15 + 1e-6;
  const DX=d=>x0+(d+win)/(2*win)*(x1-x0);
  const DY=v=>y0-(v/yMax)*(y0-y1);
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:DX(0),y1:y0,x2:DX(0),y2:y1,stroke:'var(--line)','stroke-dasharray':'3 3'}));
  const axd=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axd.textContent='displacement δ'; svg.appendChild(axd);
  const axv=SVG('text',{x:18,y:(y0+y1)/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)',transform:`rotate(-90 18 ${(y0+y1)/2})`}); axv.textContent='divergence'; svg.appendChild(axv);
  const N=200; let dk='M', df='M', maxRel=0;
  for(let i=0;i<=N;i++){ const d=-win+2*win*i/N; const kl=klBer(p,p+d); const fq=0.5*g*d*d;
    dk+=` ${DX(d).toFixed(1)} ${DY(kl).toFixed(1)}`; df+=` ${DX(d).toFixed(1)} ${DY(fq).toFixed(1)}`;
    if(kl>1e-6) maxRel=Math.max(maxRel,Math.abs(kl-fq)/kl); }
  svg.appendChild(SVG('path',{d:dk,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  svg.appendChild(SVG('path',{d:df,fill:'none',stroke:'var(--cyan)','stroke-width':2,'stroke-dasharray':'6 4'}));
  function leg(x,y,co,t,dash){ const ln=SVG('line',{x1:x,y1:y,x2:x+22,y2:y,stroke:co,'stroke-width':2.4}); if(dash) ln.setAttribute('stroke-dasharray','6 4'); svg.appendChild(ln); const tt=SVG('text',{x:x+28,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+8,'var(--yellow)','exact KL(p∥p+δ)');
  leg(x0+10,y1+24,'var(--cyan)','½ g(p) δ²  (Fisher)',true);
  const klEdge=klBer(p,p+win), fqEdge=0.5*g*win*win;
  out.textContent =
    `p = ${p.toFixed(2)},  Fisher g(p) = 1/(p(1−p)) = ${g.toFixed(3)}\n`+
    `at δ = +${win.toFixed(2)}:  exact KL = ${klEdge.toFixed(5)},  ½ g δ² = ${fqEdge.toFixed(5)}\n`+
    `max relative gap on window = ${(maxRel*100).toFixed(1)}%  (→ 0 like δ as the window shrinks)`;
}
pSl.addEventListener('input',render);
wSl.addEventListener('input',render);
render();

const svg=$('#natgrad-svg'), out=$('#natgrad-out'), kSl=$('#ng-skew'), kL=$('#ng-skew-lbl'), lrSl=$('#ng-lr'), lrL=$('#ng-lr-lbl');
const W=640,H=360, padL=44,padR=18,padT=22,padB=38;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const A=-2.6,B=2.6;   // both axes
const SX=u=>x0+(u-A)/(B-A)*(x1-x0);
const SY=v=>y0-(v-A)/(B-A)*(y0-y1);
// Objective in skewed coords (u,v): L = 1/2 (u^2 + (v/kappa)^2)*?  We model an ill-conditioned
// quadratic L(z)=1/2 z^T H z with H=diag(1, kappa^2) so the v-direction is steep.
// Fisher metric of the model in these coords is G=diag(1, kappa^2) (matching the conditioning).
// Vanilla GD: z <- z - eta*grad,  grad=H z.   Natural GD: z <- z - eta*G^{-1} grad = z - eta*(H/G) z.
function render(){
  svg.innerHTML='';
  const kappa=+kSl.value, eta=+lrSl.value; kL.textContent='κ = '+kappa.toFixed(1); lrL.textContent='η = '+eta.toFixed(2);
  const Huu=1, Hvv=kappa*kappa;       // Hessian / conditioning
  const Guu=1, Gvv=kappa*kappa;       // Fisher metric matches the conditioning
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:SY(0),x2:x1,y2:SY(0),stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:SX(0),y1:y0,x2:SX(0),y2:y1,stroke:'var(--line)'}));
  const oc=SVG('text',{x:SX(0)+6,y:SY(0)-6,'font-size':10,fill:'var(--mute)'}); oc.textContent='θ*'; svg.appendChild(oc);
  // contour ellipses of L: u^2 + kappa^2 v^2 = c
  for(const c of [0.4,1.0,1.8,2.8]){ const ru=Math.sqrt(c), rv=Math.sqrt(c)/kappa;
    const rxPix=Math.abs(SX(ru)-SX(0)), ryPix=Math.abs(SY(rv)-SY(0));
    svg.appendChild(SVG('ellipse',{cx:SX(0),cy:SY(0),rx:rxPix,ry:ryPix,fill:'none',stroke:'var(--line)','stroke-width':1})); }
  // run both descents from the same start
  const start=[2.2, 2.0/kappa + 0.4];   // start off-axis so the zig-zag is visible
  function run(natural){ let u=start[0], v=start[1]; const path=[[u,v]];
    for(let s=0;s<60;s++){ let gu=Huu*u, gv=Hvv*v; if(natural){ gu/=Guu; gv/=Gvv; } u-=eta*gu; v-=eta*gv; path.push([u,v]); if(Math.hypot(u,v)<1e-3 || Math.abs(u)>1e3 || Math.abs(v)>1e3) break; } return path; }
  function drawPath(path,color,dash){ let d='M'; for(const[u,v] of path) d+=` ${SX(u).toFixed(1)} ${SY(v).toFixed(1)}`;
    const pth=SVG('path',{d,fill:'none',stroke:color,'stroke-width':2}); if(dash) pth.setAttribute('stroke-dasharray','6 4'); svg.appendChild(pth);
    for(const[u,v] of path) svg.appendChild(SVG('circle',{cx:SX(u),cy:SY(v),r:1.8,fill:color})); }
  const vp=run(false), np=run(true);
  drawPath(vp,'var(--pink)',false);
  drawPath(np,'var(--cyan)',true);
  svg.appendChild(SVG('circle',{cx:SX(start[0]),cy:SY(start[1]),r:4.5,fill:'var(--yellow)'}));
  function leg(x,y,co,t,dash){ const ln=SVG('line',{x1:x,y1:y,x2:x+22,y2:y,stroke:co,'stroke-width':2.4}); if(dash) ln.setAttribute('stroke-dasharray','6 4'); svg.appendChild(ln); const tt=SVG('text',{x:x+28,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x1-180,y1+8,'var(--pink)','vanilla GD');
  leg(x1-180,y1+24,'var(--cyan)','natural GD',true);
  const vEnd=Math.hypot(vp[vp.length-1][0],vp[vp.length-1][1]);
  const nEnd=Math.hypot(np[np.length-1][0],np[np.length-1][1]);
  const vDiv = !isFinite(vEnd) || vEnd > 50;
  out.textContent =
    `condition number κ² = ${(kappa*kappa).toFixed(0)},  step η = ${eta.toFixed(2)}\n`+
    (vDiv ? `vanilla GD DIVERGES here (η·κ² = ${(eta*kappa*kappa).toFixed(1)} > 2): the step overshoots the steep axis\n` : `after 60 steps:  vanilla dist to θ* = ${vEnd.toFixed(3)},  natural dist = ${nEnd.toFixed(3)}\n`)+
    `G⁻¹∇L rescales each axis by the metric: the natural path is straight & κ-independent`;
}
kSl.addEventListener('input',render);
lrSl.addEventListener('input',render);
render();

const svg=$('#expfam-svg'), out=$('#expfam-out'), thSl=$('#ef-theta'), thL=$('#ef-theta-lbl'), famBtn=$('#ef-fam');
const W=640,H=360, padL=52,padR=20,padT=24,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
let bernoulli=true;
// Bernoulli: psi(t)=log(1+e^t), eta=sigma(t) in (0,1).
// Gaussian with known variance 1, mean theta: psi(t)=t^2/2, eta=t (the mean).
function psi(t){ return bernoulli ? Math.log(1+Math.exp(t)) : 0.5*t*t; }
function dpsi(t){ return bernoulli ? 1/(1+Math.exp(-t)) : t; }       // eta
function d2psi(t){ const s=1/(1+Math.exp(-t)); return bernoulli ? s*(1-s) : 1; } // Fisher
const A=-4,B=4;
const SX=t=>x0+(t-A)/(B-A)*(x1-x0);
function render(){
  svg.innerHTML='';
  const th=+thSl.value; thL.textContent='θ = '+th.toFixed(2);
  famBtn.textContent = bernoulli ? 'family: Bernoulli' : 'family: Gaussian mean';
  // y-range of psi over the window
  let pmax=Math.max(psi(A),psi(B))*1.1+0.5;
  const SY=v=>y0-(v/pmax)*(y0-y1);
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:SX(0),y1:y0,x2:SX(0),y2:y1,stroke:'var(--line)','stroke-dasharray':'3 3'}));
  const axt=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axt.textContent='natural parameter θ'; svg.appendChild(axt);
  const axp=SVG('text',{x:18,y:(y0+y1)/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)',transform:`rotate(-90 18 ${(y0+y1)/2})`}); axp.textContent='ψ(θ)'; svg.appendChild(axp);
  // convex psi
  let d='M', N=200; for(let i=0;i<=N;i++){ const t=A+(B-A)*i/N; d+=` ${SX(t).toFixed(1)} ${SY(psi(t)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d,fill:'none',stroke:'var(--violet)','stroke-width':2.4}));
  // tangent at theta: slope = eta = dpsi(theta)
  const eta=dpsi(th), p0=psi(th);
  const tL=A, tR=B; const yL=p0+eta*(tL-th), yR=p0+eta*(tR-th);
  svg.appendChild(SVG('line',{x1:SX(tL),y1:SY(yL),x2:SX(tR),y2:SY(yR),stroke:'var(--cyan)','stroke-width':1.4,'stroke-dasharray':'5 4'}));
  // point of tangency
  svg.appendChild(SVG('circle',{cx:SX(th),cy:SY(p0),r:5,fill:'var(--yellow)'}));
  // mark the slope-eta as a little rise/run triangle
  const tri=SVG('text',{x:SX(th)+10,y:SY(p0)-8,'font-size':11,fill:'var(--cyan)'}); tri.textContent='slope = η = '+eta.toFixed(3); svg.appendChild(tri);
  const fisher=d2psi(th);
  out.textContent =
    `family: ${bernoulli?'Bernoulli (θ = logit)':'Gaussian, known σ=1 (θ = mean)'}\n`+
    `natural θ = ${th.toFixed(2)}   →   dual η = ∇ψ(θ) = ${eta.toFixed(4)}` + (bernoulli?'  = σ(θ) = p':'  = mean') + `\n`+
    `Fisher G(θ) = ψ″(θ) = ${fisher.toFixed(4)}` + (bernoulli?'  = p(1−p)':'  = 1') + `\n`+
    `θ ↔ η is the Legendre transform; ψ convex ⇔ G ⪰ 0`;
}
