const svg=$('#pythag-svg'), out=$('#pythag-out'), pySl=$('#py-py'), pyL=$('#py-py-lbl'), angSl=$('#py-ang'), angL=$('#py-ang-lbl'), qSl=$('#py-q'), qL=$('#py-q-lbl'), snapBtn=$('#py-snap');
const W=640,H=360, padL=46,padR=18,padT=22,padB=38;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
// 2-D Gaussians N(eta, I): KL(N(a)||N(b)) = 1/2 |a-b|^2 — a true squared Euclidean distance,
// so Fisher = I, e- and m-geodesics are straight lines, and the Pythagorean theorem is exact
// when the legs meet at a right angle. S is an e-flat line; r is a fixed point of S; q slides
// along S. The additive identity holds exactly when q is the perpendicular foot of p onto S.
const A=-3.2,B=3.2;
const SX=u=>x0+(u-A)/(B-A)*(x1-x0);
const SY=v=>y0-(v-A)/(B-A)*(y0-y1);
function kl(a,b){ const dx=a[0]-b[0], dy=a[1]-b[1]; return 0.5*(dx*dx+dy*dy); }
// S passes through the fixed anchor c0 with direction set by the angle slider; r sits at s=2.2.
const c0=[-0.4,0.2], rS=2.2;
function render(){
  svg.innerHTML='';
  const py=+pySl.value, ang=(+angSl.value)*Math.PI/180, qt=+qSl.value;
  pyL.textContent='η_p,2 = '+py.toFixed(1); angL.textContent=(+angSl.value)+'°'; qL.textContent='s = '+qt.toFixed(1);
  const dir=[Math.cos(ang),Math.sin(ang)];                 // unit direction of S
  const p=[0.6, py];                                       // point off the submanifold
  const r=[c0[0]+rS*dir[0], c0[1]+rS*dir[1]];              // r: fixed point of S
  const q=[c0[0]+qt*dir[0], c0[1]+qt*dir[1]];              // q: slides along S
  // perpendicular foot of p onto S, as an s-value
  const footS=(p[0]-c0[0])*dir[0]+(p[1]-c0[1])*dir[1];
  const onFoot=Math.abs(qt-footS)<0.06;
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:SY(0),x2:x1,y2:SY(0),stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:SX(0),y1:y0,x2:SX(0),y2:y1,stroke:'var(--line)'}));
  const axu=SVG('text',{x:x1-6,y:SY(0)-6,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); axu.textContent='η₁'; svg.appendChild(axu);
  const axv=SVG('text',{x:SX(0)+6,y:y1+10,'font-size':11,fill:'var(--mute)'}); axv.textContent='η₂'; svg.appendChild(axv);
  // the e-flat submanifold S (a full line through the frame)
  const tBig=8; const sa=[c0[0]-tBig*dir[0],c0[1]-tBig*dir[1]], sb=[c0[0]+tBig*dir[0],c0[1]+tBig*dir[1]];
  svg.appendChild(SVG('line',{x1:SX(sa[0]),y1:SY(sa[1]),x2:SX(sb[0]),y2:SY(sb[1]),stroke:'var(--violet)','stroke-width':2}));
  const slbl=SVG('text',{x:SX(sb[0])-2,y:SY(sb[1])-6,'text-anchor':'end','font-size':11,fill:'var(--violet)','font-style':'italic'}); slbl.textContent='e-flat submanifold S'; svg.appendChild(slbl);
  // legs: m-geodesic p->q and e-geodesic (along S) q->r
  drawArrow(svg,[SX(p[0]),SY(p[1])],[SX(q[0]),SY(q[1])],{color:'var(--cyan)',markerId:'py-m',width:2.4,label:'m-geodesic'});
  drawArrow(svg,[SX(q[0]),SY(q[1])],[SX(r[0]),SY(r[1])],{color:'var(--pink)',markerId:'py-e',width:2.4,label:'e-geodesic'});
  // little right-angle square at q when q is the perpendicular foot
  if(onFoot){ const u=dir, n=[-dir[1],dir[0]]; const sz=0.28;
    const k1=[q[0]+sz*u[0],q[1]+sz*u[1]], k2=[q[0]+sz*u[0]+sz*n[0],q[1]+sz*u[1]+sz*n[1]], k3=[q[0]+sz*n[0],q[1]+sz*n[1]];
    svg.appendChild(SVG('path',{d:`M${SX(q[0])} ${SY(q[1])} L${SX(k1[0])} ${SY(k1[1])} L${SX(k2[0])} ${SY(k2[1])} L${SX(k3[0])} ${SY(k3[1])} Z`,fill:'none',stroke:'var(--green)','stroke-width':1.4})); }
  // points
  function pt(z,color,lab,dx,dy){ svg.appendChild(SVG('circle',{cx:SX(z[0]),cy:SY(z[1]),r:5.5,fill:color,stroke:'#111','stroke-width':1})); const tt=SVG('text',{x:SX(z[0])+dx,y:SY(z[1])+dy,'font-size':12,fill:color,'font-weight':600}); tt.textContent=lab; svg.appendChild(tt); }
  pt(p,'var(--yellow)','p',9,-7); pt(q,'var(--green)','q',9,16); pt(r,'var(--pink)','r',9,-7);
  // the three KLs
  const klpr=kl(p,r), klpq=kl(p,q), klqr=kl(q,r);
  const sum=klpq+klqr, resid=sum-klpr;
  out.textContent =
    `KL(N(a)∥N(b)) = ½|a−b|²  (unit-variance 2-D Gaussians, Fisher = I)\n`+
    `KL(p∥q) = ${klpq.toFixed(4)},  KL(q∥r) = ${klqr.toFixed(4)},  KL(p∥r) = ${klpr.toFixed(4)}\n`+
    `KL(p∥q)+KL(q∥r) = ${sum.toFixed(4)}   vs   KL(p∥r) = ${klpr.toFixed(4)}   (residual ${resid>=0?'+':''}${resid.toFixed(4)})\n`+
    (onFoot ? '✓ Pythagorean: m-leg ⟂ e-leg at q — KL is exactly additive'
            : '→ q is off the perpendicular foot: residual ' + resid.toFixed(3) + ' (snap q to the foot for KL additivity)');
}
pySl.addEventListener('input',render);
angSl.addEventListener('input',render);
qSl.addEventListener('input',render);
snapBtn.addEventListener('click',()=>{
  const py=+pySl.value, ang=(+angSl.value)*Math.PI/180; const dir=[Math.cos(ang),Math.sin(ang)]; const p=[0.6,py];
  const footS=(p[0]-c0[0])*dir[0]+(p[1]-c0[1])*dir[1];
  qSl.value=Math.max(-3.0,Math.min(3.0,footS)); render();
});
render();
